­main 함수는 SystemClock_Config(), InitAtcom(), InitLpwaChip(), ProcCmdParse() 함
수로 구성된다. ­SystemClock_Config() 함수는 보드 동작에 필요한 메인 클럭 설정 및 내부 클럭 
설정을 수행한다.
 { 
 /* Reset of all peripherals, Initializes the Flash interface and the Systick. */
 HAL_Init();
 /* Configure the system clock */
 SystemClock_Config();
 /* UART Init */
 InitAtCom();
 /* Initialization of lpwa SoC */
 InitLpwaChip();
 
 /* Infinite loop */
 while (1)
 {
 /* Handle UART AT commands */
 ProcCmdParse();
 
 if(test_start) 
 {
 if(send_txCnt < test_txCnt) 
 {
 if(!modem_tx_busy) 
 {
 send_txCnt++;
 SndAtCom("TX test: Send Count %d\r\n", send_txCnt);
 SndModemData();
 HAL_Delay(1000);
 }
 }
 else 
 {
 test_start = false;
 send_txCnt = 0;
 }
 }
 }
}
